//! Per-repository git hooks installed by mox.
//!
//! The pre-commit hook is the last line of defence against committing heavy
//! files or obvious secrets. It is generated for new repositories only; an
//! existing hook is never overwritten.

use anyhow::{Context, Result};
use std::path::{Path, PathBuf};

pub const PRE_COMMIT: &str = r#"#!/bin/sh
# Generated by mox — do not edit. Blocks heavy files and obvious secrets.
limit=2097152
fail=0
for f in $(git diff --cached --name-only --diff-filter=ACM); do
  [ -f "$f" ] || continue
  size=$(wc -c < "$f" | tr -d ' ')
  if [ "$size" -gt "$limit" ]; then
    echo "mox pre-commit: $f is $size bytes (limit $limit, 2 MiB)" >&2
    fail=1
  fi
  case "$f" in
    *.env.example) ;;
    *.env|*.env.*|*.pem|*.key|*id_rsa*|*id_ed25519*)
      echo "mox pre-commit: refusing secret-looking file $f" >&2
      fail=1
      ;;
  esac
  if grep -IqE '(BEGIN (RSA|OPENSSH|EC|DSA) PRIVATE KEY|gh[pousr]_[A-Za-z0-9]{20,}|sk-[A-Za-z0-9]{20,}|AKIA[0-9A-Z]{16}|xox[baprs]-[A-Za-z0-9-]{10,})' "$f"; then
    echo "mox pre-commit: secret pattern found in $f" >&2
    fail=1
  fi
done
if [ "$fail" -ne 0 ]; then
  echo "mox pre-commit: commit blocked; delete the file or record a human check" >&2
fi
exit "$fail"
"#;

/// Install the hook if the repository has no pre-commit hook yet.
pub fn install(repo: &Path) -> Result<Option<PathBuf>> {
    if !repo.join(".git").is_dir() {
        return Ok(None);
    }
    let hooks_dir = repo.join(".git/hooks");
    std::fs::create_dir_all(&hooks_dir)
        .with_context(|| format!("creating {}", hooks_dir.display()))?;
    let path = hooks_dir.join("pre-commit");
    if path.exists() {
        return Ok(None);
    }
    std::fs::write(&path, PRE_COMMIT)
        .with_context(|| format!("writing hook {}", path.display()))?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o755))?;
    }
    Ok(Some(path))
}

/// True when a repository has the mox pre-commit hook.
pub fn has_hook(repo: &Path) -> bool {
    let path = repo.join(".git/hooks/pre-commit");
    match std::fs::read_to_string(path) {
        Ok(text) => text.contains("Generated by mox"),
        Err(_) => false,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::process::Command;

    fn git_repo() -> tempfile::TempDir {
        let dir = tempfile::tempdir().unwrap();
        let status = Command::new("git")
            .args(["init", "-q"])
            .current_dir(dir.path())
            .status()
            .unwrap();
        assert!(status.success());
        dir
    }

    fn run_hook(repo: &Path) -> std::process::Output {
        Command::new(repo.join(".git/hooks/pre-commit"))
            .current_dir(repo)
            .output()
            .unwrap()
    }

    #[test]
    fn installs_executable_hook_once() {
        let repo = git_repo();
        let installed = install(repo.path()).unwrap().unwrap();
        assert!(has_hook(repo.path()));
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mode = std::fs::metadata(&installed).unwrap().permissions().mode();
            assert_eq!(mode & 0o777, 0o755);
        }
        assert!(install(repo.path()).unwrap().is_none());
    }

    #[test]
    fn blocks_large_staged_files() {
        let repo = git_repo();
        install(repo.path()).unwrap();
        std::fs::write(repo.path().join("big.bin"), vec![b'x'; 3 * 1024 * 1024]).unwrap();
        assert!(Command::new("git")
            .args(["add", "big.bin"])
            .current_dir(repo.path())
            .status()
            .unwrap()
            .success());
        let output = run_hook(repo.path());
        assert!(!output.status.success());
        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(stderr.contains("2 MiB"), "{stderr}");
    }

    #[test]
    fn blocks_secret_patterns_and_secret_files() {
        let repo = git_repo();
        install(repo.path()).unwrap();
        std::fs::write(
            repo.path().join("config.txt"),
            "token = ghp_abcdefghijklmnopqrstuvwxyz0123456789\n",
        )
        .unwrap();
        std::fs::write(repo.path().join(".env"), "X=1\n").unwrap();
        for file in ["config.txt", ".env"] {
            Command::new("git")
                .args(["add", file])
                .current_dir(repo.path())
                .status()
                .unwrap();
        }
        let output = run_hook(repo.path());
        assert!(!output.status.success());
        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(stderr.contains("secret"), "{stderr}");
    }

    #[test]
    fn allows_normal_and_env_example_files() {
        let repo = git_repo();
        install(repo.path()).unwrap();
        std::fs::write(repo.path().join("main.rs"), "fn main() {}\n").unwrap();
        std::fs::write(repo.path().join(".env.example"), "X=changeme\n").unwrap();
        for file in ["main.rs", ".env.example"] {
            Command::new("git")
                .args(["add", file])
                .current_dir(repo.path())
                .status()
                .unwrap();
        }
        let output = run_hook(repo.path());
        assert!(
            output.status.success(),
            "{}",
            String::from_utf8_lossy(&output.stderr)
        );
    }

    #[test]
    fn skips_when_git_is_not_initialised() {
        let dir = tempfile::tempdir().unwrap();
        assert!(install(dir.path()).unwrap().is_none());
        assert!(!has_hook(dir.path()));
    }
}
